def solve():
    solutions = []
    for n in range(1001):
        p_n = n**3 + 4*n**2 + 6*n + 4
        if p_n <= 0:
            continue
        # Check if p_n is a power of 2 and 5
        temp = p_n
        while temp > 0 and temp % 2 == 0:
            temp //= 2
        while temp > 0 and temp % 5 == 0:
            temp //= 5

        if temp == 1:
            # Check if p_n divides 20^(n+1)
            # Actually, p_n = 2^a * 5^b, we need to check if a <= 2(n+1) and b <= n+1.
            # Let's find a and b.
            a = 0
            b = 0
            curr = p_n
            while curr % 2 == 0:
                curr //= 2
                a += 1
            while curr % 5 == 0:
                curr //= 5
                b += 1

            if a <= 2*(n+1) and b <= (n+1):
                solutions.append(n)
    return solutions

print(solve())

import math

def find_solutions():
    solutions = []
    # Check k^2 + 1 = 5^d
    for d in range(101):
        k2 = 5**d - 1
        k = math.isqrt(k2)
        if k*k == k2:
            k = int(k)
            n = k - 1
            if n >= 0:
                # Check if n+2 = k+1 = 2^a 5^b
                val = k + 1
                temp = val
                while temp > 0 and temp % 2 == 0:
                    temp //= 2
                while temp > 0 and temp % 5 == 0:
                    temp //= 5
                if temp == 1:
                    solutions.append(n)

    # Check k^2 + 1 = 2 * 5^d
    for d in range(101):
        k2 = 2 * 5**d - 1
        k = math.isqrt(k2)
        if k*k == k2:
            k = int(k)
            n = k - 1
            if n >= 0:
                # Check if n+2 = k+1 = 2^a 5^b
                val = k + 1
                temp = val
                while temp > 0 and temp % 2 == 0:
                    temp //= 2
                while temp > 0 and temp % 5 == 0:
                    temp //= 5
                if temp == 1:
                    solutions.append(n)

    return sorted(list(set(solutions)))

print(find_solutions())

def check_large_d():
    solutions = []
    for d in range(1001):
        k2 = 2 * 5**d - 1
        k = int(k2**0.5)
        if k*k == k2:
            solutions.append((k, d))
    return solutions

